import{_ as i,l as o,o as e,c as n,v as t,p as s,x as l,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"落后者缓解","description":"","frontmatter":{"title":"落后者缓解","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/straggler-mitigation.md","filePath":"llm/straggler-mitigation.md","lastUpdated":1789023840000}'),h={name:"llm/straggler-mitigation.md"};function A(c,a,m,_,u,T){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="落后者缓解" tabindex="-1">落后者缓解 <a class="header-anchor" href="#落后者缓解" aria-label="Permalink to &quot;落后者缓解&quot;">​</a></h1><div class="epigraph"><p>同步迭代的时间等于最慢那张卡；热专家、坏 GPU、抖动的数据加载，都会让其余千卡陪着等。</p><footer>—— 据 Dean 等对同步系统落后者的经典观察；Jiang 等 MegaScale 的大集群训练实践</footer></div><p><a href="/llm/elastic-training">上一课</a>处理已经死掉的 rank。更常见的是：心跳还在，集合通信每次都最后完成。本课不重讲世界缩小。缺口是识别与缓解落后者——热 MoE 专家、SP 组里的慢注意力、磁盘偶发、时钟降频——以及哪些手段会破坏训练重放。训练重放需要确定性；本课的缓解若包含「丢弃慢微批」，就必须声明对梯度的影响。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1F1B、All-Reduce、All-to-All、Ulysses 置换全是栅栏。分布的尾延迟决定步时。MegaScale 在万卡上把落后者当成一等故障：不杀进程也要把尾部剪掉或隔离。来源分三类。计算：路由把 token 堆到少数专家，或某卡降频。通信：拓扑不对称，某跨架链路拥塞。数据：某个 rank 的加载器在解压超大文档。数据课的长文档上采样若没做长度分桶，会系统性制造数据落后者。</p><p>误杀的代价是弹性风暴。缓解应先分级：观测 → 迁移负载 → 换节点，而不是第一步就 shrink 世界。</p><h3 id="moe-热专家是结构性落后者" tabindex="-1">MoE 热专家是结构性落后者 <a class="header-anchor" href="#moe-热专家是结构性落后者" aria-label="Permalink to &quot;MoE 热专家是结构性落后者&quot;">​</a></h3><p>负载均衡失败时，落后者每周出现。应先把辅助损失或偏置调到容量曲线平坦，再谈硬件。把结构性问题当坏卡，会永远换到下一张仍热的卡。</p><p><span class="marginnote">profiler 只看均值会看不见尾部。应报每 rank 步时的 P99，以及 All-to-All 等待分解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每步记录各 rank 在各栅栏上的等待时间。超过阈值：先把该 rank 的数据管道与计算分开看（加载器队列是否空）。数据问题：预取加深、把超长样本改到专用微批、或对该文档切片。计算问题：查 GPU 错误计数、功耗、是否与检查点 writer 抢拷贝。通信问题：对照拓扑放置是否把 TP/EP 跨到了弱链路。</p><p>缓解手段按侵入性排序：绑核与 NUMA、隔离异步保存到少数 rank、动态把热专家副本增加（若框架支持）、把该节点标脏并在下一检查点弹性换出。不要在步内丢弃未完成的微批充数，除非实验明确接受有偏梯度。</p><h3 id="与重叠的关系" tabindex="-1">与重叠的关系 <a class="header-anchor" href="#与重叠的关系" aria-label="Permalink to &quot;与重叠的关系&quot;">​</a></h3><p>重叠把均值变好看，尾部仍在 wait。落后者会使「通信暴露时间」在单 rank 爆炸，其余 rank 的重叠窗口空转。治理落后者往往比再调一版 DualPipe 更赚。</p><p><span class="marginnote">训练中评测若打在同步路径上（每个 n 步全员等评测），评测机会成为周期性落后者。应异步、降频、或只用子集 rank。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同步 SGD 的一步是 \\(\\max_i T_i\\)。优化均值 \\(T\\) 而不优化 \\(\\max\\)，集群越大越亏。这与数据并行线性加速的假设相反：加速比被尾部卡住。弹性处理的是 \\(T_i=\\infty\\)；本课处理 \\(T_i\\) 处于分布右尾。</p>',17)),(e(),s(E,null,{default:l(()=>[p(r,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20BAR%5B%22%E9%9B%86%E5%90%88%E9%80%9A%E4%BF%A1%E6%A0%85%E6%A0%8F%22%5D%20--%3E%20WAIT%5B%22%E6%AF%8F%20rank%20%E7%AD%89%E5%BE%85%E5%88%86%E8%A7%A3%22%5D%0A%20%20WAIT%20--%3E%20DAT%5B%22%E6%95%B0%E6%8D%AE%E7%AE%A1%E9%81%93%3F%22%5D%0A%20%20WAIT%20--%3E%20CMP%5B%22%E8%AE%A1%E7%AE%97%20%2F%20%E9%99%8D%E9%A2%91%3F%22%5D%0A%20%20WAIT%20--%3E%20NET%5B%22%E6%8B%93%E6%89%91%E6%8B%A5%E5%A1%9E%3F%22%5D%0A%20%20WAIT%20--%3E%20MOE%5B%22%E7%83%AD%E4%B8%93%E5%AE%B6%3F%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>缓解不能承诺消除物理故障，只降低活着的尾延迟。确定性重放要求：不能把「随机跳过慢 batch」当作默认。下一课规定如何在需要时重跑同一串微批，以区分软件 bug 与真正的坏硬件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲掉卡拉起；只补活着的尾延迟。</li><li>先分解等待：数据、计算、网络、MoE 负载。</li><li>侵入性从小到大；步内丢微批会偏梯度。</li><li>P99 与栅栏分解比平均 MFU 更有用。</li><li>出处：Jiang et al., MegaScale, 2024；Dean 等对同步落后者的讨论；对照 MoE 负载均衡。</li></ul>',4))])}const k=i(h,[["render",A]]);export{f as __pageData,k as default};
